import * as THREE from './vendor/three.module.js';
import {buildCar,disposeCar} from './car-visuals.js';
import {bend,rise,heading} from './track.js';
export function createGhostView(scene){let car=null,key='';return {update(s,spec){const pose=s.ghostPose,visible=s.gameMode==='trial'&&!!pose&&Math.abs(pose.distance-s.distance)<300&&(Math.abs(pose.distance-s.distance)>2.8||Math.abs(pose.x-s.x)>1.5);if(!visible){if(car)car.visible=false;return;}const next=spec.id+JSON.stringify(s.appearance);if(next!==key){if(car){scene.remove(car);disposeCar(car);}key=next;car=buildCar(spec,s.appearance,'#5be7ff');car.traverse(o=>{if(o.isMesh){o.castShadow=o.receiveShadow=false;o.material.transparent=true;o.material.opacity=.26;o.material.depthWrite=false;}});scene.add(car);}car.visible=true;const f=pose.distance-s.distance;car.position.set(pose.x+bend(f,s.distance,s.trackProfile),.06+rise(f,s.distance,s.trackProfile)+pose.jumpY,-f);car.rotation.set(0,Math.PI-heading(f,s.distance,s.trackProfile)-pose.steering*.12,0);},dispose(){if(car){disposeCar(car);scene.remove(car);}}};}
